      [[9, 1.9], [16, 1.9], [23, 1.9], [9, -1.9], [16, -1.9], [23, -1.9], [-9, 1.9], [-9, -1.9], [-16, 1.9], [-16, -1.9], [1.9, 10], [-1.9, 10], [1.9, -13], [-1.9, -13]]
